using System.Collections.Generic;

// Declarar e instanciar una lista vacía
List<string> nombres = new List<string>();

// Agregar elementos
nombres.Add("Ana");
nombres.Add("Luis");
nombres.Add("Mia");

// Acceder por índice (igual que un array)
Debug.Log(nombres[0]); // "Ana"

// Count: número de elementos actuales
Debug.Log(nombres.Count); // 3

// Verificar si existe un elemento
bool existe = nombres.Contains("Luis"); // true

// Obtener el índice de un elemento
int idx = nombres.IndexOf("Mia"); // 2

// Eliminar por valor
nombres.Remove("Ana"); // elimina la primera ocurrencia

// Eliminar por índice
nombres.RemoveAt(0); // elimina el elemento en la posición 0

// Recorrer con foreach
foreach (string nombre in nombres)
{
    Debug.Log(nombre);
}

